  munch (alloc_W2 lo sp A size ff fp) m mx -> wmono asegs m mx ->
  (forall m', munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z mx m' -> wmono asegs mx m' ->
     rw_cells asegs m' A [CB (Z.to_nat size) (firstn (Z.to_nat size) junkB)] /\ rw_cells asegs m' (A + size) (CookieCells j7)) ->
