    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp xs1 (Z_to_bv 64 A) a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) xs3 xs4 xs5 xs6 xs7 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) xs10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 0xa8298) fc None mx (seg_rom asegs)).
